begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "9ddb926f-37b4-5652-953d-5df5c064fe6c", "feature_slug": "missions", "title": "Condition Types", "content": "| Type | Source Table | Event Trigger | Filters Available |\n|------|--------------|---------------|-------------------|\n| `purchase` | `purchase_ledger` | status=''completed'' | products, SKUs, categories, brands, stores, amounts |\n| `points_earned` | `wallet_ledger` | transaction_type=''earn'', currency=''points'' | earn_source_type |\n| `tickets_earned` | `wallet_ledger` | transaction_type=''earn'', currency=''ticket'' | ticket_type_id |\n| `form_submission` | `form_submissions` | status=''completed'' | form_id |\n| `referral_signup` | `referral_ledger` | signed_up_at IS NOT NULL | — |\n| `referral_purchase` | `referral_ledger` | first_purchase_at IS NOT NULL | — |\n\n### Measurement Types\n\n| Type | Behavior | Example |\n|------|----------|---------|\n| `count` | Each event adds +1 | \"Make 5 purchases\" |\n| `sum` | Each event adds its value | \"Spend 5000 THB\" |\n\nBinary events (forms, referrals) always use count logic.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Mission.md#L290 Condition Types", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7781240c0b5bd7e9a86d9828a40124d13ba86efc854aacb2798a4882c39dd924", "truncated": false}, "is_active": true}, {"id": "f31b23c7-0583-5130-bae5-c1cd9b776552", "feature_slug": "missions", "title": "Per-Condition JSONB Progress Tracking", "content": "### Core Concept\n\nOne JSONB field (`condition_progress`) stores progress for both mission types. The key structure and update strategy differ:\n\n| Mission Type | Key Structure | Update Strategy |\n|--------------|---------------|-----------------|\n| Standard | `condition_id` (UUID) | Parallel—each event updates its matching condition |\n| Milestone | `level_N` | Waterfall—event fills from first incomplete level, overflow continues to next |\n\n### Standard Mission Structure\n\n```json\n{\n  \"0d284fa9-b6d8-4159-b95c-4a16e110cbc2\": {\n    \"type\": \"purchase\",\n    \"target\": 1000,\n    \"current\": 750,\n    \"condition_id\": \"0d284fa9-b6d8-4159-b95c-4a16e110cbc2\"\n  },\n  \"76add59b-8e7b-4b18-a1c4-3e3bdbf71113\": {\n    \"type\": \"points_earned\",\n    \"target\": 100,\n    \"current\": 82,\n    \"condition_id\": \"76add59b-8e7b-4b18-a1c4-3e3bdbf71113\"\n  }\n}\n```\n\n**Parallel Update Logic:** When a purchase event arrives, only the `purchase` condition updates. When a points_earned event arrives, only that condition updates. Mission completes when ALL conditions reach their targets.\n\n### Milestone Mission Structure\n\n```json\n{\n  \"level_1\": {\n    \"type\": \"purchase\",\n    \"target\": 500,\n    \"current\": 500,\n    \"completed_at\": \"2025-12-30T14:13:25Z\",\n    \"condition_id\": \"7c4db085-7446-45ba-92b1-674b46eee69f\"\n  },\n  \"level_2\": {\n    \"type\": \"purchase\",\n    \"target\": 2000,\n    \"current\": 2000,\n    \"completed_at\": \"2025-12-30T14:13:37Z\",\n    \"condition_id\": \"772c1c36-0574-45c2-8aeb-490f06c3a65d\"\n  },\n  \"level_3\": {\n    \"type\": \"purchase\",\n    \"target\": 5000,\n    \"current\": 700,\n    \"completed_at\": null,\n    \"condition_id\": \"1cca15ff-945c-42b3-99b4-e0b3bbc9c4f0\"\n  }\n}\n```\n\n**Waterfall Update Logic:** When a purchase event arrives:\n1. Find first incomplete level (where `completed_at` is null)\n2. Add amount to that level''s `current`\n3. If `current >= target`, mark completed, calculate overflow\n4. Apply overflow to next level, repeat until depleted\n\n**Example:**\n- User has Level 1 at 300/500, Level 2 at 0/2000\n- Purchase of 400 THB arrives\n- Level 1: 300 + 400 = 700, needs 500, overflow = 200\n- Level 1 completes (500/500), Level 2 gets overflow (200/2000)", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Mission.md#L73 Per-Condition JSONB Progress Tracking", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c0e7c740191464c5ebaf1d7cc7c9cee57a3e5978fee7973f4cb5959245102613", "truncated": false}, "is_active": true}, {"id": "13c2b610-1536-5b3b-b49a-c4c076d74357", "feature_slug": "missions", "title": "7. Business Rules", "content": "**Rule:** Standard missions use AND logic — all conditions must reach their targets for the mission to complete.\n**Example:** Mission has \"Spend 5,000 THB\" (at 5,000) and \"Earn 500 points\" (at 420). Not complete — both must hit target.\n\n**Rule:** Milestone missions use sequential waterfall — overflow from completing one level automatically applies to the next.\n**Example:** Level 1 at 300/500, Level 2 at 0/2,000. Purchase of 400 arrives → Level 1: 500/500 (complete, overflow 200) → Level 2: 200/2,000.\n\n**Rule:** `button_action` follows strict priority order. The first matching condition wins.\n**Example:** Member has unclaimed completions AND hasn''t accepted → `claim_outcome` wins over `join_mission` because it''s higher priority.\n\n**Rule:** Manual activation blocks all progress tracking until the member explicitly joins.\n**Example:** Auto mission: member''s purchases count immediately. Manual mission: purchases before `accepted_at` are ignored.\n\n**Rule:** Milestone missions cannot have reset frequency — this is enforced as a database constraint.\n**Example:** Creating a milestone mission with `reset_frequency = daily` → rejected.\n\n**Rule:** Empty filter arrays mean unrestricted. `product_ids = []` means all products qualify.\n**Example:** Condition with no product filters → any purchase counts toward progress.\n\n**Rule:** The AND operator on condition filters requires all filter criteria to match within a single event.\n**Example:** `product_ids = [A, B]` with AND operator → a single purchase must include both products A and B.\n\n**Rule:** Progress loops allow repeated completions. When `allow_progress_loop = true`, progress resets after completion and the mission can be completed again.\n**Example:** Daily challenge with loop enabled → member can complete and claim every day.\n\n**Rule:** Exclusivity groups prevent double-counting. A qualifying event updates only one mission within a `progress_exclusivity_group`.\n**Example:** Two missions in group \"q1_spending\" — a purchase event only advances whichever mission the system evaluates first.\n\n**Rule:** Claim limits cap how many times rewards can be collected within a time period.\n**Example:** Claim limit: per_user, 3/month → fourth completion in the same month does not distribute rewards.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/missions.md#L291 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d585eb10026f07b954193063c13f507f17678c7140f99e230b762fd53534b2c5", "truncated": false}, "is_active": true}, {"id": "37adabd3-dd30-5318-81a6-c2a12f0ef81d", "feature_slug": "missions", "title": "3. Configuration Reference", "content": "### Basic Info\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Name | Mission display name | \"Big Spender Challenge\" | Required |\n| Code | Unique identifier code | \"BIG_SPENDER_Q1\" | Required |\n| Type | Standard or Milestone | `standard` | Required |\n| Description | Admin-facing description | \"Q1 spending challenge\" | Empty |\n| Start date | When mission becomes active | 2025-01-01 | No restriction |\n| End date | When mission expires | 2025-03-31 | No restriction |\n| Is active | Enable/disable toggle | true | true |\n| Images | Mission display images | PNG/JPG URLs | Empty array |\n\n### Activation & Claiming\n\n| Setting | What it controls | Options | Default |\n|---|---|---|---|\n| Activation type | Auto-track or require opt-in | `auto` / `manual` | `auto` |\n| Claim type | Auto-reward or require claim | `auto` / `manual` | `auto` |\n| Reset frequency | How often progress resets | `NULL` / `daily` / `monthly` | `NULL` |\n| Reset mode | Calendar vs per-user reset | `global` / `user_specific` | `global` |\n\n### Progress Controls\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Allow progress loop | Repeat mission after completion | true | false |\n| Max loops per transaction | Cap repeats from single event | 3 | NULL (unlimited) |\n| Progress exclusivity group | Prevent double-counting across missions | \"q1_spending\" | NULL |\n| Claim exclusivity group | Only one claimable in group | \"q1_prizes\" | NULL |\n| Milestone allow skip | Allow skipping milestone levels | false | false |\n\n### Conditions (per condition row)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Condition type | Event source | `purchase` | Required |\n| Measurement type | Count vs sum | `sum` | Required |\n| Target value | Completion threshold | 5000 | Required |\n| Operator | AND/OR for array filters | `AND` | `AND` |\n| Product/SKU/Category/Brand IDs | Product filters | [uuid, uuid] | Empty (all) |\n| Store attribute set | Location filter | uuid | NULL (all) |\n| Min/Max transaction amount | Per-event amount range | 100 / 5000 | NULL |\n| Form ID | Specific form (form_submission type) | uuid | NULL |\n| Earn source type | Point earn source filter | [\"purchase\"] | Empty |\n| Ticket type ID | Ticket type filter | [uuid] | Empty |\n| Tier IDs | Eligible tiers | [Gold, Platinum] | Empty (all) |\n\n### Milestones (milestone missions only)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Milestone level | Level number (sequential) | 1, 2, 3 | Required |\n| Milestone name | Display name | \"Bronze\", \"Silver\" | Required |\n| Badge URL | Level badge image | https://cdn.../bronze.png | NULL |\n| Display order | UI ordering | 1, 2, 3 | Same as level |\n\n### Outcomes (per outcome row)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Outcome type | Reward type | `points` / `tickets` / `reward` | Required |\n| Amount | Points/tickets to grant | 500 | Required for points/tickets |\n| Milestone level | Which level triggers this (milestone only) | 2 | NULL (standard) |\n| Entity ID | Linked reward (reward type) | uuid | NULL |\n\n### Limits\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Scope (progress) | Who the progress limit applies to | `per_user` | — |\n| Scope (claim) | Who the claim limit applies to | `per_user` | — |\n| Amount | Maximum count in period | 5 | — |\n| Time unit | Period of limit | `day` / `month` | — |\n\n### Display Settings\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| User perspective | Member-facing description | \"Complete to earn 500 pts\" | NULL |\n| Description goal | Goal description text | \"Spend 5,000 THB this month\" | NULL |\n| Description T&C | Terms and conditions | Rich text | NULL |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/missions.md#L41 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a4bf1f728a2af0793bd4a9a27f762cabb5c4ff887b963f2f188120659310087a", "truncated": false}, "is_active": true}, {"id": "4da7bca9-70c3-50a3-a907-25b085aee6d4", "feature_slug": "missions", "title": "Database Schema", "content": "### mission_progress Table\n\n| Column | Type | Purpose |\n|--------|------|---------|\n| `id` | uuid | Primary key |\n| `user_id` | uuid | User being tracked |\n| `mission_id` | uuid | Mission reference |\n| `merchant_id` | uuid | Merchant context |\n| `current_progress` | numeric | Legacy—sum of all progress (backwards compatibility) |\n| `condition_progress` | jsonb | **V2: Per-condition/level progress tracking** |\n| `lifetime_completions` | integer | Total completions ever |\n| `unclaimed_completions` | integer | Pending claims (manual-claim missions) |\n| `last_progress_at` | timestamptz | Last progress update |\n| `accepted_at` | timestamptz | When user accepted (manual missions) |\n\n### mission_conditions Table\n\n| Column | Type | Purpose |\n|--------|------|---------|\n| `id` | uuid | Condition identifier (used as JSONB key for standard) |\n| `mission_id` | uuid | Parent mission |\n| `condition_type` | enum | Event type to track |\n| `measurement_type` | enum | ''count'' or ''sum'' |\n| `target_value` | numeric | Completion threshold |\n| `milestone_level` | integer | Level number (milestone missions only) |\n| `operator` | enum | ''AND'' or ''OR'' for array filters |\n| `product_ids`, `sku_ids`, `category_ids`, `brand_ids` | uuid[] | Product filters |\n| `store_attribute_set_id` | uuid | Location filter |\n| `min_transaction_amount`, `max_transaction_amount` | numeric | Amount range |\n\n### mission_milestones Table\n\n| Column | Type | Purpose |\n|--------|------|---------|\n| `id` | uuid | Milestone identifier |\n| `mission_id` | uuid | Parent mission |\n| `milestone_level` | integer | Level number (1, 2, 3...) |\n| `milestone_name` | text | Display name (\"Bronze\", \"Silver\", \"Gold\") |\n| `milestone_description` | text | Level description |\n| `display_order` | integer | UI ordering |", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Mission.md#L310 Database Schema", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5c7247ae5d70572ca488a0d9914c86e01abfc470dd9128866030bd350a98cdc8", "truncated": false}, "is_active": true}, {"id": "567b55bd-a756-5e74-b615-0b2d8eb66ce3", "feature_slug": "missions", "title": "BFF Functions (Frontend API)", "content": "### bff_get_user_missions\n\nReturns list of missions for a user with progress summary.\n\n**Endpoint:** `POST /rest/v1/rpc/bff_get_user_missions`\n\n**Parameters:**\n| Parameter | Type | Default | Description |\n|-----------|------|---------|-------------|\n| `p_user_id` | uuid | `auth.uid()` | Target user (admin override) |\n| `p_include_inactive` | boolean | false | Include inactive missions |\n\n### bff_get_mission_detail\n\nReturns comprehensive mission details including conditions, outcomes, and progress.\n\n**Endpoint:** `POST /rest/v1/rpc/bff_get_mission_detail`\n\n**Parameters:**\n| Parameter | Type | Default | Description |\n|-----------|------|---------|-------------|\n| `p_mission_id` | uuid | required | Mission to retrieve |\n| `p_user_id` | uuid | `auth.uid()` | Target user (admin override) |\n\n### bff_claim_mission\n\nClaims mission outcomes for user.\n\n**Endpoint:** `POST /rest/v1/rpc/bff_claim_mission`\n\n**Parameters:**\n| Parameter | Type | Default | Description |\n|-----------|------|---------|-------------|\n| `p_mission_id` | uuid | required | Mission to claim |\n| `p_user_id` | uuid | `auth.uid()` | Target user (admin override) |\n| `p_milestone_level` | integer | null | Specific milestone to claim (milestone missions only) |\n\n### button_action Field\n\nBoth list and detail BFF functions return a `button_action` field for frontend button binding:\n\n| Value | Condition | Frontend Action |\n|-------|-----------|-----------------|\n| `claim_outcome` | Has unclaimed completions AND manual claim | Call `bff_claim_mission` |\n| `join_mission` | Not accepted AND manual activation | Call `accept_mission` |\n| `claimed` | All conditions/milestones completed & claimed | Disabled button |\n| `view_progress` | Has progress record | Navigate to detail |\n| `view_details` | Default (no progress) | Navigate to detail |\n\n**Priority Order (checked top-to-bottom):**\n1. `claim_outcome` → unclaimed_completions > 0 AND claim_type = ''manual''\n2. `join_mission` → accepted_at IS NULL AND activation_type = ''manual''\n3. `claimed` → all conditions met (100%) and claimed\n4. `view_progress` → has mission_progress record\n5. `view_details` → fallback\n\n**Frontend JavaScript Example:**\n```javascript\nconst buttonAction = missionData?.button_action;\n\nconst textMap = {\n  ''claim_outcome'': ''รับรางวัล'',\n  ''join_mission'': ''เข้าร่วมภารกิจ'',\n  ''claimed'': ''รับแล้ว'',\n  ''view_progress'': ''ดูความคืบหน้า'',\n  ''view_details'': ''ดูรายละเอียด''\n};\n\nconst buttonText = textMap[buttonAction] || ''ดูรายละเอียด'';\nconst isDisabled = buttonAction === ''claimed'';\n```", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Mission.md#L425 BFF Functions (Frontend API)", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "1ee27756752247914b1b823897d2a014a08fbba3416e2b1904ab188d735d5eb4", "truncated": false}, "is_active": true}, {"id": "b612712c-cfa1-54bf-832b-2fd344500cca", "feature_slug": "missions", "title": "2. Key Concepts", "content": "**Standard Mission** — A mission where all conditions must be met simultaneously. Each condition tracks independently in parallel. Mission completes when every condition reaches its target. Example: \"Spend 5,000 THB AND earn 500 points\" requires both to reach target.\n\n**Milestone Mission** — A mission with sequential levels (1 → 2 → 3), each having a distinct target and reward. Members advance through levels in order. Example: Level 1 \"Spend 500 THB\" → Level 2 \"Spend 2,000 THB\" → Level 3 \"Spend 5,000 THB\".\n\n**Condition** — A trackable requirement within a mission. Defined by a condition type (what event), measurement type (count or sum), and target value (threshold). Standard missions can have multiple conditions; milestone missions have one condition per level.\n\n**Condition Type** — The event source that triggers progress. Six types: `purchase` (completed purchases), `points_earned` (point earn events), `tickets_earned` (ticket earn events), `form_submission` (completed forms), `referral_signup` (referred user signs up), `referral_purchase` (referred user makes first purchase).\n\n**Measurement Type** — How events contribute to progress. `count`: each qualifying event adds +1 (e.g., \"make 5 purchases\"). `sum`: each event adds its value (e.g., \"spend 5,000 THB\"). Binary events (forms, referrals) always use count.\n\n**Waterfall** — Milestone-specific overflow logic. When a purchase exceeds the remaining target for the current level, the excess applies to the next level. Example: Level 1 needs 200 more, purchase is 400 → Level 1 completes, 200 overflow goes to Level 2.\n\n**Activation Type** — `auto`: progress tracks for all members immediately. `manual`: members must explicitly join the mission before progress counts.\n\n**Claim Type** — `auto`: rewards distribute immediately upon completion. `manual`: members must tap a claim button to receive rewards.\n\n**button_action** — A computed field returned by the BFF that tells the frontend which button to show. Priority order: `claim_outcome` (unclaimed completions exist, manual claim) → `join_mission` (not yet accepted, manual activation) → `claimed` (all complete and claimed) → `view_progress` (has progress record) → `view_details` (fallback).\n\n**Reset Frequency** — How often progress resets. `NULL`: accumulates indefinitely. `daily`: resets at midnight. `monthly`: resets on the 1st. Milestone missions cannot have reset frequency.\n\n**Reset Mode** — When reset frequency is set: `global` resets all users at the same calendar time. `user_specific` resets relative to each user''s `period_started_at`.\n\n**Exclusivity Group** — A string tag that prevents double-counting. `progress_exclusivity_group`: a single event only updates one mission in the group. `claim_exclusivity_group`: only one mission in the group can be claimed.\n\n**Outcome** — The reward distributed upon completion. Types include points, tickets, or a specific reward entity (linked by `entity_id`). Milestone missions assign outcomes per level.\n\n**Mission Status** — Derived from `is_active`, `start_date`, and `end_date`: Active (on and within window), Inactive (toggled off), Scheduled (start date in future), Expired (end date in past).", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/missions.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3697915469ecac4816927a65e614e48734317aeb68e47b19903677818b91d97a", "truncated": false}, "is_active": true}, {"id": "0af774f6-1152-5cbc-9ea3-9e8beeb73bd8", "feature_slug": "missions", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch**: \"Missions are challenges that reward members for completing specific actions — like spending a certain amount, referring friends, or earning points. Members see their progress in real-time and collect rewards when they finish. You can think of them as quests in a game.\"\n\n**Top 5 support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Member''s mission progress isn''t updating\" | Progress updates via event streaming (CDC → Kafka → Inngest). Check if the qualifying event actually occurred (purchase completed, points earned). If activation_type is manual, confirm the member joined first. |\n| \"Member completed the mission but didn''t get a reward\" | If claim_type is manual, member must tap the claim button. Check if claim limits or exclusivity groups are blocking. |\n| \"Mission shows ''Inactive'' but should be running\" | Check is_active toggle, start_date (future = Scheduled), and end_date (past = Expired). |\n| \"Progress reset unexpectedly\" | Check reset_frequency (daily/monthly) and reset_mode (global vs user_specific). Progress resets are by design. |\n| \"Member wants to join but there''s no join button\" | If activation_type is auto, there''s no join step — progress tracks automatically. If manual, check that button_action is rendering correctly. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/missions.md#L221 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "16c9a97346c84cebb90d325d276e6814dbbcf9bb7589fe350cefd622b172b092", "truncated": false}, "is_active": true}, {"id": "4b2b626c-bc1c-5cb1-b5bd-e9483e99e55a", "feature_slug": "missions", "title": "1. Overview", "content": "Missions are goal-based challenges that guide members through specific actions — making purchases, earning points, referring friends, submitting forms — and reward them upon completion. They are the primary gamification mechanic in the loyalty platform, turning routine behavior into structured quests with visible progress and tangible outcomes.\n\nTwo mission types serve different engagement patterns. **Standard Missions** require members to satisfy multiple conditions simultaneously (AND logic) — for example, \"spend 5,000 THB AND earn 500 points\" — with each condition tracking progress independently in parallel. **Milestone Missions** define sequential levels (Bronze → Silver → Gold), each with its own target and reward. Progress waterfalls through levels: overflow from completing one level automatically applies to the next, so a single large purchase can complete multiple milestones at once.\n\nKey differentiators: (1) **event-driven progress** — purchases, point earnings, referrals, and form submissions automatically update mission progress via CDC event streaming without polling; (2) **waterfall overflow** — milestone missions never waste progress, excess from one level flows to the next; (3) **configurable activation and claiming** — merchants choose whether members opt in manually or track automatically, and whether rewards are distributed immediately or require a claim action; (4) **per-condition JSONB tracking** — granular progress stored per condition or level, enabling multi-axis challenges in a single mission.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/missions.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7c33966fb00d173be767fbcedec68322bd8237f140b9892f70f18470519bc1e1", "truncated": false}, "is_active": true}, {"id": "e4ee107b-f0fc-5e03-adb4-5e37b6245ff0", "feature_slug": "missions", "title": "8. Related Features", "content": "| Feature | Connection to Missions |\n|---|---|\n| Currency | Points and tickets granted as mission outcomes are credited to the member''s wallet. See `Currency.md`. |\n| Rewards | Missions can grant specific rewards (linked by entity_id) as completion outcomes. See `Reward.md`. |\n| Referral | `referral_signup` and `referral_purchase` condition types track referral activity as mission progress. See `Referral.md`. |\n| Purchase | `purchase` condition type tracks completed purchases. Product, category, brand, and store filters narrow which purchases qualify. See `Purchase_Transaction.md`. |\n| Activity/Earning | `points_earned` and `tickets_earned` condition types track earn events. See `Activity_Based_Earning.md`. |\n| Forms | `form_submission` condition type tracks completed form submissions. See `Forms.md`. |\n| Store Classification | `store_attribute_set_id` filter on conditions restricts which store locations qualify. See `Store_Attribute_Classification.md`. |\n| Tier | `tier_ids` on conditions can gate mission participation by member tier. See `Tier.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/missions.md#L323 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "32c1a42abb1bf70ca8f9d56233e718f9f12e015255b6a98269ad922013172491", "truncated": false}, "is_active": true}, {"id": "d3cb9693-e902-51ef-923c-02315d7154e2", "feature_slug": "missions", "title": "Architecture", "content": "```\n┌─────────────────────────────────────────────────────────────────────────┐\n│                           Event Sources                                  │\n├─────────────────┬─────────────────┬─────────────────┬───────────────────┤\n│ purchase_ledger │  wallet_ledger  │form_submissions │  referral_ledger  │\n└────────┬────────┴────────┬────────┴────────┬────────┴─────────┬─────────┘\n         │                 │                 │                  │\n         └────────────────┬┴─────────────────┴──────────────────┘\n                          │\n                          ▼\n                 ┌────────────────┐\n                 │  Debezium CDC  │\n                 │  (Supabase)    │\n                 └───────┬────────┘\n                         │\n                         ▼\n                 ┌────────────────┐\n                 │  Kafka Topics  │\n                 │  (Upstash)     │\n                 └───────┬────────┘\n                         │\n                         ▼\n                 ┌────────────────┐\n                 │MissionConsumer │◄── Redis Pre-filter Cache\n                 │(crm-event-     │    (active missions lookup)\n                 │ processors)    │\n                 └───────┬────────┘\n                         │\n                         ▼\n                 ┌────────────────┐\n                 │ Inngest Cloud  │\n                 │ mission/evaluate│\n                 └───────┬────────┘\n                         │\n                         ▼\n                 ┌────────────────┐\n                 │inngest-mission │\n                 │   -serve       │\n                 │ (Edge Function)│\n                 └───────┬────────┘\n                         │\n                         ▼\n         ┌───────────────┴───────────────┐\n         │     PostgreSQL Functions      │\n         ├───────────────────────────────┤\n         │fn_evaluate_mission_conditions │\n         │fn_update_mission_progress     │\n         │fn_process_mission_outcomes    │\n         └───────────────┬───────────────┘\n                         │\n                         ▼\n                 ┌────────────────┐\n                 │mission_progress│\n                 │(condition_     │\n                 │ progress JSONB)│\n                 └────────────────┘\n```", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Mission.md#L13 Architecture", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b24edbd852da0a1724ad8d72289dee217f9c6e7b6e5252d91a6dba8b965fb132", "truncated": false}, "is_active": true}, {"id": "ff8526f0-7103-5e11-a0a5-9c4aebac90a4", "feature_slug": "missions", "title": "Event Flow", "content": "### 1. CDC Capture\n\nDebezium captures changes from source tables and streams to Kafka:\n\n| Source Table | Kafka Topic | Condition Type |\n|--------------|-------------|----------------|\n| `purchase_ledger` | `crm_cdc.public.purchase_ledger` | `purchase` |\n| `wallet_ledger` | `crm_cdc.public.wallet_ledger` | `points_earned`, `tickets_earned` |\n| `form_submissions` | `crm_cdc.public.form_submissions` | `form_submission` |\n| `referral_ledger` | `crm_cdc.public.referral_ledger` | `referral_signup`, `referral_purchase` |\n\n### 2. MissionConsumer Processing\n\nThe consumer service (`crm-event-processors`) receives CDC messages and:\n\n1. **Parses Debezium message** - Extracts `after` payload with row data\n2. **Decodes decimal values** - Debezium encodes DECIMAL/NUMERIC as base64; consumer decodes them\n3. **Checks Redis cache** - Fast lookup: does this merchant have active missions for this condition type?\n4. **Publishes to Inngest** - Sends `mission/evaluate` event with user, merchant, event data\n\n```typescript\n// Debezium decimal decoding example\n// Input: \"JxA=\" (base64-encoded 100.00)\n// Output: 100.00\nconst amount = decodeDebeziumDecimal(after.final_amount, 2);\n```\n\n### 3. Inngest Workflow: mission/evaluate\n\nThe `inngest-mission-serve` Edge Function orchestrates evaluation:\n\n```typescript\ninngest.createFunction(\n  { id: \"mission-evaluate\", concurrency: { limit: 50 } },\n  { event: \"mission/evaluate\" },\n  async ({ event, step }) => {\n    const { user_id, merchant_id, mission_id, event_type, event_data, trigger_id } = event.data;\n    \n    // Step 1: Evaluate conditions\n    const increments = await step.run(\"evaluate-conditions\", async () => {\n      return await supabase.rpc(\"fn_evaluate_mission_conditions\", {\n        p_mission_id: mission_id,\n        p_merchant_id: merchant_id,\n        p_user_id: user_id,\n        p_event_type: event_type,\n        p_event_data: event_data\n      });\n    });\n    \n    // Step 2: Update progress\n    const result = await step.run(\"update-progress\", async () => {\n      return await supabase.rpc(\"fn_update_mission_progress\", {\n        p_user_id: user_id,\n        p_mission_id: mission_id,\n        p_merchant_id: merchant_id,\n        p_increments: increments,\n        p_trigger_type: event_type,\n        p_trigger_id: trigger_id\n      });\n    });\n    \n    // Step 3: Process outcomes if completed\n    if (result.newly_completed?.length > 0) {\n      await step.run(\"process-outcomes\", async () => {\n        return await supabase.rpc(\"fn_process_mission_outcomes\", {...});\n      });\n    }\n  }\n);\n```\n\n### 4. PostgreSQL Functions\n\n**`fn_evaluate_mission_conditions`**\n\nEvaluates event against mission conditions and returns increments:\n\n- For **standard missions**: Returns `{\"condition-uuid\": increment}`\n- For **milestone missions**: Returns `{\"level_1\": increment}` (always targets level_1, waterfall handles distribution)\n\nThe function checks:\n- Does event_type match condition_type?\n- Do product/category/brand filters match?\n- Are amount thresholds satisfied?\n- Does store location match attribute set?\n\n**`fn_update_mission_progress`**\n\nApplies increments to `condition_progress` JSONB:\n\n```sql\n-- Determine update strategy\nIF mission_type = ''milestone'' THEN\n  -- Waterfall: fill from first incomplete level\n  FOR level_key IN SELECT key FROM levels ORDER BY level_num LOOP\n    IF current < target THEN\n      remaining = target - current;\n      applied = LEAST(increment, remaining);\n      new_current = current + applied;\n      increment = increment - applied;  -- overflow\n      \n      IF new_current >= target THEN\n        -- Mark level completed\n        condition_progress[level_key].completed_at = NOW();\n        newly_completed = array_append(newly_completed, level_key);\n      END IF;\n    END IF;\n  END LOOP;\nELSE\n  -- Parallel: update matching condition directly\n  condition_progress[condition_id].current += increment;\nEND IF;\n```\n\n**`fn_process_mission_outcomes`**\n\nDistributes rewards when milestones/conditions complete:\n\n- Creates `wallet_ledger` entries for points/tickets\n- Creates `redemption_pool` entries for physical rewards\n- Logs to `mission_log_completion` and `mission_log_outcome_distribution`", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Mission.md#L145 Event Flow", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8a329fdd4c852743dccdab628d68decac89fbe5c40021d2049d85407b3a78b55", "truncated": false}, "is_active": true}, {"id": "f04008b2-a598-5d07-948b-ef8e0c0dd901", "feature_slug": "missions", "title": "Mission Domain Reference", "content": "**Keywords:** mission, quest, challenge, milestone, standard mission, condition, progress, waterfall, level, claim, join, accept, mission progress, condition progress, button action\n**Source:** `Mission.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `bff_get_user_missions(p_user_id, p_include_inactive)` | `p_user_id (uuid, default auth.uid())`, `p_include_inactive (bool)` | Mission list with progress summary | 427–438 |\n| `bff_get_mission_detail(p_mission_id, p_user_id)` | `p_mission_id (uuid)`, `p_user_id (uuid, default auth.uid())` | Full mission details + conditions + outcomes + progress | 440–450 |\n| `bff_claim_mission(p_mission_id, p_user_id, p_milestone_level)` | `p_mission_id (uuid)`, `p_user_id (uuid)`, `p_milestone_level (int, nullable)` | Claim result | 452–463 |\n| `bff_report_missions(p_from, p_to, p_frequency, p_filters)` | Admin report. Filters: `mission_id`, `mission_type`, `is_claimed`, `outcome_type`, `tier_id`, `persona_id`. | Summary, time series, mission/type/outcome breakdowns | Reports RPC suite |\n| `bff_report_missions_rows(p_from, p_to, p_filters, p_limit, p_offset, p_sort)` | Admin report drilldown. Sorts: `completed_at_desc`, `completed_at_asc`, `claimed_at_desc`, `points_desc`. | Completion rows and `total_count` | Reports RPC suite |\n**Key Business Rules (summary):**\n- Standard missions: all conditions must reach target (AND logic); each condition tracks independently\n- Milestone missions: sequential levels with waterfall overflow (completing level 1 feeds excess into level 2)\n- `button_action` drives FE button text/state: `claim_outcome` > `join_mission` > `claimed` > `view_progress` > `view_details`\n- `progress_activation_type`: `auto` (tracks all users) vs `manual` (requires accept call)\n- `claim_type`: `auto` (rewards immediately) vs `manual` (user must claim)\n- Milestone missions cannot have reset frequency", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/mission.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "847cd5899bb51735b9fe1116f9d1d9f67d85c33f9bb5d78c2737292c9dcfb142", "truncated": false}, "is_active": true}, {"id": "c9182337-16db-5490-a01f-a0109e6c235c", "feature_slug": "missions", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| `activation_type = manual`, member hasn''t joined | `button_action = join_mission`, no progress tracking |\n| `activation_type = auto` | Progress tracks immediately for all members |\n| `claim_type = manual`, mission completed | `button_action = claim_outcome` |\n| `claim_type = auto`, mission completed | Outcomes distributed automatically, `button_action = claimed` |\n| `reset_frequency = daily` | Progress resets at midnight (global) or relative to user (user_specific) |\n| `reset_frequency = NULL`, milestone mission | Progress accumulates indefinitely (only valid option for milestones) |\n| Standard mission, 2 conditions, only 1 met | Mission not complete — ALL conditions required |\n| Milestone mission, Level 1 at 300/500, purchase of 400 | Level 1 completes (500/500), 200 overflow → Level 2 (200/target) |\n| `allow_progress_loop = true`, completed once | Mission resets and can complete again |\n| `is_active = false` | Mission not visible to members, no progress tracking |\n| `start_date` in future | Status = Scheduled, not available to members |\n| No outcomes configured | Mission completes but no rewards distributed |\n\n**Business rules as assertions:**\n\n- ASSERT: Standard mission completes only when ALL conditions reach target simultaneously\n- ASSERT: Milestone waterfall applies overflow from completed level to next level in sequence\n- ASSERT: `button_action` priority is claim_outcome > join_mission > claimed > view_progress > view_details\n- ASSERT: Manual activation requires `accepted_at` to be set before progress counts\n- ASSERT: Milestone missions cannot have reset_frequency (constraint enforced)\n- ASSERT: Condition filters (product_ids, category_ids, etc.) with AND operator require all to match in a single event\n- ASSERT: Delete cascades in order: conditions → outcomes → limit_progress → limit_claim → mission\n\n**Status model:**\n\n| Field | Values | Meaning |\n|---|---|---|\n| `is_active` | `true` / `false` | Master toggle for the mission |\n| Mission Status (derived) | Active / Inactive / Scheduled / Expired | Computed from is_active + date window |\n| `accepted_at` | NULL / timestamp | Whether member has joined (manual activation) |\n| `unclaimed_completions` | integer | Pending manual claims |\n| `lifetime_completions` | integer | Total completions ever |\n| `condition_progress` | JSONB | Per-condition or per-level current values |", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/missions.md#L221 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2cd1d5ad114bbeac2912e081c6cb755f6f7fb6af24004f6599e84d01f3626df2", "truncated": false}, "is_active": true}, {"id": "d6ecf9b1-693c-504e-8376-5bc263caa4af", "feature_slug": "missions", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current route | Data source |\n|---|---|---|\n| Homepage mission section | `/` (block-based) | `bff_get_display_blocks_cached(p_page: ''homepage'')` |\n| Mission list | Homepage navigation grid | `bff_get_user_missions` |\n| Mission detail | Drawer or detail view | `bff_get_mission_detail(p_mission_id)` |\n\n### 5a. Discover Missions\n\n1. Member opens the homepage — navigation grid block includes a \"Missions\" icon\n2. Tapping \"Missions\" navigates to a mission list view showing available missions\n3. Each mission card shows: image, name, type badge, progress indicator, and the button_action CTA\n\n### 5b. View Mission Detail\n\n1. Member taps a mission card → detail view opens\n2. Detail shows: mission image, name, description, goal description, terms & conditions\n3. For Standard missions: progress bars for each condition (e.g., \"3,500 / 5,000 THB\", \"420 / 500 points\")\n4. For Milestone missions: level progression display showing completed levels (with badges) and current level progress\n5. CTA button text driven by `button_action` field\n\n### 5c. Join a Manual Mission\n\n1. If `activation_type = manual` and member hasn''t joined: button shows \"Join Mission\" (`join_mission`)\n2. Member taps → calls `accept_mission` → `accepted_at` timestamp set on progress record\n3. Button updates to \"View Progress\" (`view_progress`)\n4. Progress starts tracking from this point forward\n\n### 5d. Track Progress\n\n1. Progress updates automatically as qualifying events occur (purchases, point earnings, etc.)\n2. Standard missions show parallel progress bars — each condition independently advancing\n3. Milestone missions show sequential level progression — current level highlighted with progress bar\n4. No manual action needed — CDC events flow through Kafka → Inngest → PostgreSQL functions\n\n### 5e. Claim Rewards\n\n1. If `claim_type = auto`: rewards distribute immediately upon completion — member sees notification\n2. If `claim_type = manual`: button shows \"Claim Reward\" (`claim_outcome`)\n3. Member taps → calls `bff_claim_mission` → outcomes distributed (points/tickets/rewards credited)\n4. For milestone missions: each level can be claimed independently via `p_milestone_level` parameter\n5. After all claims: button shows \"Claimed\" (`claimed`, disabled)", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/missions.md#L173 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d8adb18f76b4f4760b91d6bee0cb7a7b81f6ae29a9947f8a14dcb8f135261062", "truncated": false}, "is_active": true}, {"id": "9efd66fe-e795-592d-b468-3e05eb88971d", "feature_slug": "missions", "title": "6b. For Marketing", "content": "**Value proposition**: Missions transform passive loyalty membership into active engagement. Instead of simply accumulating points, members pursue structured challenges with clear goals and visible progress — creating a game-like experience that drives repeat visits and higher spend.\n\n**Use-case stories:**\n\n1. **Monthly spending challenge** — \"Spend 5,000 THB this month\" with daily reset visibility. Members track daily progress, creating urgency to visit before month-end. Auto-activation ensures all members participate without friction.\n\n2. **Onboarding quest** — Standard mission: \"Make 3 purchases AND refer 1 friend AND complete your profile form.\" Combines multiple engagement actions into a single quest that new members complete in their first 30 days.\n\n3. **Tiered spending milestones** — Milestone mission: Bronze (500 THB → 50 points), Silver (2,000 THB → 200 points), Gold (5,000 THB → 500 points + exclusive reward). Waterfall overflow means a single 3,000 THB purchase can complete Bronze and partially fill Silver, rewarding big spenders proportionally.\n\n4. **Seasonal campaign** — Time-boxed mission (start/end dates) tied to a holiday promotion. Manual claim type creates a moment of delight when members tap to collect their reward.", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/missions.md#L221 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3ddc2805c9ce98e82b85d4fb066b4e377d12b96cf6d1e94ffb9bafbbf09a028f", "truncated": false}, "is_active": true}, {"id": "2fac5c48-e0f4-5340-9e6c-46f73f638d59", "feature_slug": "platform-overview", "title": "1. The Customer Lifecycle", "content": "Each stage maps to a module. A customer progresses through all four:\n\n| Stage | Module | What Happens |\n|---|---|---|\n| **Convert** | Loyalty | Register via LINE or phone OTP. Build unified profile. Earn points from any channel — POS, e-commerce, marketplace, receipt upload, QR scan. |\n| **Engage** | Loyalty + AMP | Tier progression, missions, referrals, check-in streaks. AMP sends automated welcome series, birthday offers, re-engagement campaigns. |\n| **Activate** | AMP + AI | AI agent inside workflows evaluates full customer context (tier, purchases, sentiment, conversations). Decides: act (send offer), wait (wrong timing), or skip (no intervention needed). |\n| **Support** | CS | Customer asks a question on any channel. AI resolves autonomously or escalates to a human agent with full context. Resolution can trigger loyalty actions (bonus points, voucher). |\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/platform-overview.md#L15 1. The Customer Lifecycle", "metadata": {"source_doc_type": "platform_overview", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "platform-overview", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "190c70726e91d5ae9154571940fe149c493cd0cb2812abee7b9d416339c7d7a1", "truncated": false}, "is_active": true}, {"id": "bec40991-7fec-5c28-86f8-5448bf49a162", "feature_slug": "platform-overview", "title": "6. AI Across the Platform", "content": "AI is a capability layer, not a module. It runs through all three modules with shared infrastructure.\n\n| Where | What It Does |\n|---|---|\n| CS autonomous agent | Handles conversations end-to-end: intent → knowledge → procedure → actions → response |\n| CS voice agent | Same reasoning as chat. Different orchestration for sub-second voice latency. |\n| CS live assist | Augments human agents: drafts, summaries, copilot, suggestions, translation |\n| CS quality | Post-resolution: auto-QA scoring, sentiment, gap detection, Watchtower monitoring |\n| AMP decisioning | Per-customer marketing decisions inside workflows: act/wait/skip with goal optimization |\n| Loyalty pricing | 4-dimension matching (tier × user type × persona × tags) for dynamic reward point costs |\n\nCS and AMP AI share the same action catalog, content library, and customer context. A CS conversation that reveals frustration feeds into AMP''s decision context — the AI agent in a workflow can account for recent service interactions when choosing whether to send a promotion.\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/platform-overview.md#L181 6. AI Across the Platform", "metadata": {"source_doc_type": "platform_overview", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "platform-overview", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5cca6b14414b5ae5d3a9462cb56cb9b24349e979f80e0eed86fdaf94d439adab", "truncated": false}, "is_active": true}, {"id": "57c99686-4f44-5efe-9046-c5bfa6781cb4", "feature_slug": "platform-overview", "title": "7. Audience Entry Points", "content": "Each audience should start reading from a different place. The platform overview (this doc) orients everyone; the feature guides go deep.\n\n| Audience | Start Here | Then Read |\n|---|---|---|\n| **Marketing** | This doc: Sections 1-2 (lifecycle + connections) for positioning. Section 3-5 prose intros for module value props. | Individual guides: Section 1 (Overview) and Section 6b (For Marketing) in each. |\n| **Customer Success** | This doc: Section 2 (connections) for FAQ answers. Module sections for feature inventory. | Individual guides: Section 6a (For Customer Success) for onboarding scripts and troubleshooting. |\n| **Product** | This doc: Section 2 (connections + shared capabilities) for dependency mapping. Section 6 (AI) for cross-module capabilities. | Individual guides: Section 1 (Overview) for orientation, Section 8 (Related Features) for dependencies, Section 3 for config inventory. |\n| **Testing** | This doc: Section 2 (data flows) for cross-module test scenarios. | Individual guides: Section 6c (For Testers) for config→behavior mappings, Section 7 (Business Rules) for assertions. |\n\n### Cross-Module Test Scenarios\n\n| Scenario | Verify |\n|---|---|\n| Purchase → Loyalty → AMP | Points earned → tier evaluated → workflow triggered → message sent |\n| CS → Loyalty bridge | AI queries tier/points → awards courtesy points → wallet updated |\n| AMP → content library | Workflow sends shared resource → channel-specific formatting applied |\n| Identity linking | CS contact linked to loyalty member → AI sees full loyalty context |\n| Action catalog consistency | New action registered → available in CS AI, AMP AI, macros |\n| Voice ↔ chat parity | Same procedure via chat and voice → same resolution, same actions |\n\n### Onboarding Sequence\n\n1. **Loyalty first** — tiers, earning rules, reward catalog. Members need something to earn before automation or service add value.\n2. **Connect channels** — LINE OA, marketplace shops, Shopify. Connections serve both AMP and CS.\n3. **Enable AMP** — First workflows: welcome series, post-purchase follow-up, birthday campaign.\n4. **Enable CS** — Knowledge base articles, procedures for top intents, brand voice. Turn on AI per channel.\n\n### Common Questions\n\n| Question | Answer |\n|---|---|\n| CS without Loyalty? | Yes. Identity bridge is nullable. AI resolves with channel data + knowledge base. No CRM bridge errors. |\n| Loyalty without CS? | Yes. Members interact through the loyalty app. No CS dependencies. |\n| Loyalty without AMP? | Yes. Loyalty events don''t fail when no workflows exist. |\n| AMP without Loyalty? | No. AMP triggers on loyalty events and executes loyalty actions. |\n| AMP without CS? | Yes. Messages deliver independently of CS inbox configuration. |\n| How does AI know the customer? | CS: queries loyalty via CRM bridge when identity is linked. AMP: full customer profile pre-fetched from data layer. |\n| Multiple channels, same customer? | One profile. LINE, phone, Shopee Chat — same conversation history and context. |", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/platform-overview.md#L198 7. Audience Entry Points", "metadata": {"source_doc_type": "platform_overview", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "platform-overview", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b211c28ec49ea03e64285c9f8c5ec344618deab42e4a291439dd4dbe3aab4e2f", "truncated": false}, "is_active": true}, {"id": "9aee6f0e-b8d5-532b-8cf1-d6966a4ba8cd", "feature_slug": "platform-overview", "title": "2. How the Modules Connect", "content": "### Data Flows\n\n| From → To | What Flows | Example |\n|---|---|---|\n| **Loyalty → AMP** | Events: purchase, tier upgrade, mission complete, inactivity | Purchase event triggers a post-purchase follow-up workflow |\n| **AMP → CS** | Campaign context on conversations | Customer asks about an offer they received; CS agent sees the campaign details |\n| **CS → Loyalty** | Loyalty actions from within conversations | AI agent awards 500 courtesy points after resolving a shipping complaint |\n| **CS → AMP** | Sentiment and resolution data | AMP condition: \"skip if customer had a negative CS interaction in the last 7 days\" |\n| **AMP → Loyalty** | CRM actions executed by workflows | Workflow assigns \"VIP Event Attendee\" tag after purchase threshold met |\n\n### Shared Capabilities\n\nFive capabilities span multiple modules. Each is configured once and available everywhere it applies.\n\n| Capability | What It Is | Modules |\n|---|---|---|\n| **Action catalog** | Single registry of actions: award points, send messages, create vouchers, assign tags. Register once, use across CS AI, AMP AI, and rule-based workflows. | All |\n| **Content library** | Quick replies, media, links, rich content. Same content used in CS responses and AMP messages. | CS, AMP |\n| **Action macros** | Multi-step action templates with three-layer guardrails (system ceiling → caller constraints → runtime limits). | CS, AMP |\n| **Channel connections** | One credential (LINE OA, Shopee, etc.) can serve AMP messaging and CS conversations simultaneously. Scope array controls which modules access which credential. | CS, AMP |\n| **Translation system** | Four languages (EN, TH, JA, ZH). Fallback chain: requested → merchant default → English. Covers member-facing content and UI text. See [translation-system.md](translation-system.md). | All |\n| **Admin role UI config** | Per-role settings beyond permissions: custom default landing page (redirect on login), sidebar visibility toggle, hidden menu module categories, and a configurable floating bottom navigation bar (icon + label + route per button). Enables purpose-built admin UIs — e.g. a frontline field role that sees only a floating shortcut bar with no sidebar. Configured in `admin_roles.config`. | All |\n\n### Customer Identity\n\n| Context | Identity | How It Works |\n|---|---|---|\n| Loyalty | Member account | Authenticated via LINE or phone OTP during registration |\n| CS | Contact record | Resolved from platform identity — LINE user ID, phone number, email, Shopee chat ID |\n| Bridge | CS contact → Loyalty member | Nullable link. When set, CS AI can query tier, points balance, purchase history, tags, personas. When unset, CS operates with channel data only. |\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/platform-overview.md#L28 2. How the Modules Connect", "metadata": {"source_doc_type": "platform_overview", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "platform-overview", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2955483f7d7f2fe7a78327f7fa2e8153012cd72e510628f1eb7d1f2d9d7db05f", "truncated": false}, "is_active": true}, {"id": "7a6abe93-e48b-56fc-8da3-f79868680f6c", "feature_slug": "platform-overview", "title": "3. Loyalty", "content": "Turn every customer into a known, engaged, rewarded member — regardless of where they buy.\n\nMost loyalty platforms cover one purchase channel. This one covers online stores, physical POS, marketplaces (Shopee, Lazada, TikTok Shop), and distributor channels (receipt upload, QR scan). The 2×2 matrix: online/offline × 1st party/3rd party — no customer is invisible.\n\n| Feature | What It Does | Guide |\n|---|---|---|\n| Points & Wallet | Double-entry ledger. Points (fungible) and tickets (non-fungible per type). Earn factors, multipliers, expiry, reversals at original rates. | [currency.md](currency.md) |\n| Tiers | Ranking with skip-level upgrades, multi-path qualification (points OR spend OR orders), maintain-or-downgrade deadlines, five window types, burn rate conversion, persona-based structures. | [tiers.md](tiers.md) |\n| Rewards | Catalog with 4-dimension dynamic pricing (tier × persona × user type × tags). Always picks the customer-favorable price. Promo code distribution, stock control, four fulfillment methods, Shopify discount sync. | [rewards.md](rewards.md) |\n| Missions | Standard (all conditions in parallel, AND logic) and milestone (sequential levels with waterfall carry-over). Condition types: purchase, points, referral, form. Auto/manual join and claim. Reset frequency. | [missions.md](missions.md) |\n| Tags & Personas | Two-layer classification. Persona = one per customer (business identity). Tags = unlimited (behavioral attributes). Both feed eligibility, pricing, campaign targeting. | [tags-and-personas.md](tags-and-personas.md) |\n| Referral | Dual rewards (inviter + invitee). Trigger on signup or first purchase. Configurable limits per period per user type. Referrals count toward mission progress. | [referral.md](referral.md) |\n| Activity-Based Earning | Image upload → admin review → currency via 2D matrix (activity type × category). Custom field definitions. Frequency limits. | [activity-based-earning.md](activity-based-earning.md) |\n| Purchase Transactions | Append-only ledger (refunds create new records, never modify originals). Currency award triggers. E-commerce multi-status mapping. | [purchase-transactions.md](purchase-transactions.md) |\n| Check-in | Daily check-in with streak-based escalating rewards. | [checkin.md](checkin.md) |\n| Stored Value Cards | Prepaid card balance management. | [stored-value-cards.md](stored-value-cards.md) |\n| Forms & Profile | Default + custom fields, conditional visibility, PDPA consent, address management. | [forms.md](forms.md) |\n| Store Classification | Three-tier hierarchy (category → attribute → sub-attribute). Attribute sets group stores for business rule targeting. | [store-classification.md](store-classification.md) |\n| Marketplace Integration | Shopify, Lazada, Shopee, TikTok Shop. Order sync, order claim, reward distribution. | [marketplace-integration.md](marketplace-integration.md) |\n| Authentication | LINE Login + phone OTP. Multi-method auth per merchant. Progressive profiling. Custom JWT. | [authentication-and-signup.md](authentication-and-signup.md) |\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/platform-overview.md#L63 3. Loyalty", "metadata": {"source_doc_type": "platform_overview", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "platform-overview", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b7c11520df670fb5378baea493ebbc5f54d9a052ec07e8478fc41762b7eba3c3", "truncated": false}, "is_active": true}, {"id": "972fc13b-2b59-558d-b949-797a96ba7fcf", "feature_slug": "platform-overview", "title": "4. Marketing Automation (AMP)", "content": "Two engines on the same workflow canvas: rule-based (if X then Y) and AI agent (given a goal, decide per customer).\n\n### Rule-Based Workflows\n\n| Aspect | Details |\n|---|---|\n| **Triggers** | Purchase, tier upgrade, mission complete, signup, tag change, birthday, inactivity, audience entry/exit, form submission. Auto-derived from workflow conditions. |\n| **Nodes** | Condition (branch on customer data), Wait (duration or time), Message (LINE/SMS/Email), Action (CRM operations), Agent (AI decision) |\n| **Conditions** | AND/OR groups across purchases, wallet, tiers, tags, forms, custom fields. Time-aware. True/false branching. |\n| **Execution** | Per-customer journeys. Immutable event log. Delivery funnel: sent → delivered → opened. Duplicate prevention. Exit conditions. |\n\n### AI Agent Node\n\n| Aspect | Details |\n|---|---|\n| **Input** | Full customer context pre-fetched: profile, purchases, tier, tags, past campaigns, constraints |\n| **Decision** | ACT (select and execute an action), WAIT (defer to better timing), or SKIP (no intervention needed) |\n| **Goals** | What to optimize: repurchase rate, churn reduction, AOV increase. Multiple goals with weights. |\n| **Constraints** | Budget limits, frequency caps, per-action guardrails |\n| **Measurement** | Attributes business outcomes (purchases, tier upgrades) to agent actions |\n\n### Supporting Capabilities\n\n| Capability | Details |\n|---|---|\n| **Audiences** | Dynamic (condition-based, auto-updating) and manual (explicit lists). Trigger workflows on entry/exit. Use as condition filters. |\n| **Actions** | Award points/tickets, create vouchers, assign/remove tags, change persona, adjust earn factors, send LINE/SMS/Email, manage audience membership |\n| **Messaging** | Unified delivery across LINE, SMS, Email. Templates with dynamic variables. Delivery tracking. Rate limiting. |\n| **Analytics** | Workflow funnels, message delivery rates, AI agent ACT/WAIT/SKIP distribution, outcome attribution, A/B comparison |\n\n→ Guides: [amp-workflows.md](amp-workflows.md), [amp-ai-decisioning.md](amp-ai-decisioning.md)\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/platform-overview.md#L88 4. Marketing Automation (AMP)", "metadata": {"source_doc_type": "platform_overview", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "platform-overview", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "9d0407cb7bb9ebbc0ae1188591c7ed9ab2fa5792c740e3d6d95d10b3a09f3790", "truncated": false}, "is_active": true}, {"id": "285239bf-4e91-51ad-a192-38c41d810022", "feature_slug": "platform-overview", "title": "5. Customer Service (CS)", "content": "Three operational levels work simultaneously on every conversation:\n\n| Level | What It Does | When It Applies |\n|---|---|---|\n| **AI Agent** | Autonomous resolution: intent detection → procedure execution → marketplace/loyalty actions → response in brand voice | Every conversation. Resolves the majority without human involvement. |\n| **Rules Engine** | Deterministic if/then: auto-reply, auto-assign, auto-tag, auto-escalate based on keyword/intent/sentiment triggers | Runs alongside AI and human agents for predictable automations. |\n| **Human Agent** | Complex/sensitive cases. AI-augmented: draft replies, conversation summaries, knowledge copilot, action suggestions, real-time translation. | Escalated from AI or assigned via rules/routing. |\n\n### Two Modalities\n\n**Chat** — 10 channel types: LINE, WhatsApp, Facebook Messenger, Instagram DM, Shopee Chat, Lazada Chat, TikTok Chat, Email, Web Widget, SMS.\n\n**Voice** — Phone calls with real-time AI: speech-to-text → reasoning → text-to-speech. Same knowledge base, procedures, and actions as chat. Inbound + outbound.\n\n### AI Agent Capabilities\n\n| Capability | Details |\n|---|---|\n| **Intent** | Automatic detection, entity extraction (order numbers, platform, product names), multi-turn tracking, topic change recognition |\n| **Knowledge** | Semantic search across uploaded docs, website crawls, product catalogs. Gap detection surfaces unanswered questions. Custom answers override AI for specific queries. |\n| **Procedures (AOPs)** | Per-intent playbooks. Three flexibility modes: strict (compliance — follow exactly), guided (standard — adapt order/wording), agentic (advisory only). Automatic versioning. |\n| **Marketplace actions** | Order lookup, cancel, refund, stock check, price check, product search, promotion check, shipping status — across Shopee, Lazada, TikTok, Shopify |\n| **Loyalty actions** | Award points, create vouchers, check status, assign tags, update persona — via CRM bridge |\n| **Brand voice** | Tone/formality/terminology config. Forbidden topics. Escalation triggers. Per-procedure overrides. Per-action constraints. Hallucination verification step. |\n| **Customer memory** | Auto-extracted after resolution. Persists across sessions. Categories: preferences, issues, outcomes. Expiration and erasure per PDPA. |\n\n### Human Agent Workspace\n\n| Capability | Details |\n|---|---|\n| **Unified inbox** | All channels in one view. Filters: status, channel, assignee, team, priority, tags. Routing: round-robin, least-busy, skill-based. Collision detection. |\n| **AI live assist** | Draft replies (edit/approve/discard), escalation summaries, knowledge copilot sidebar (natural language questions → sourced answers), action suggestions, real-time translation |\n| **Tickets & SLA** | Lifecycle: New → Open → In Progress → Waiting → Resolved → Closed. Response/resolution targets. Business hours. Breach escalation. Multi-conversation tickets. |\n| **Teams** | Team structure, skill-based routing, agent status (online/away/offline), concurrent conversation limits, supervisor view |\n| **Quality** | Auto-QA scorecards. Watchtower: always-on monitoring with natural language criteria. CSAT surveys. Intent/sentiment analytics. AI confidence tracking. |\n\n→ Guides: [cs-conversations.md](cs-conversations.md), [cs-knowledge-base.md](cs-knowledge-base.md), [cs-channels.md](cs-channels.md)\n\n### Planned Guides\n\n| Feature | Covers |\n|---|---|\n| CS AI System | Knowledge library, customer context, memory, reasoning, guardrails, procedures, copilot |\n| CS Actions | Marketplace actions, CRM bridge, custom API builder, action governance |\n| CS Unified Inbox | Ticket lifecycle, views/filters, agent workspace, supervisor, collision detection |\n| CS SLA Management | SLA policies, business hours, breach escalation |\n| CS Rules Engine | Deterministic if/then automation |\n| CS Live Assist | Draft replies, summaries, knowledge copilot, translation |\n| CS Analytics & QA | Metrics, Watchtower, auto-QA, CSAT |\n| CS Voice | Voice AI, STT/TTS, inbound/outbound, recording, transfer |\n| Resource Content | Shared content library: quick replies, media, links, rich content |\n| Action Macros | Multi-step action templates with three-layer guardrails |\n\n---", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/platform-overview.md#L124 5. Customer Service (CS)", "metadata": {"source_doc_type": "platform_overview", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "platform-overview", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d3ab8d350073c57e6813e6f439ace92c273e2f39bd75cb4f615e0bedeac0f25f", "truncated": false}, "is_active": true}, {"id": "f0af6968-7a11-523b-99db-9695e942ec38", "feature_slug": "purchase-transactions", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Receipt Uploads | `/receipts-upload` | `v_receipt_upload_list`, `bff_approve_receipt_upload()` |\n| Customer 360 | `/customer-360/{userId}` | Customer profile with purchase history tab |\n\nThere is no dedicated \"Purchase List\" admin page. Transactions are created by external systems (POS, e-commerce webhooks, API calls) or through the Receipt Uploads approval flow. Admins interact with purchases in two contexts:\n\n### 4a. Approve a Receipt Upload (Creates Purchase Record)\n\n1. From **Receipt Uploads**, admin sees an IndexTable of member-submitted receipt images with status tabs (All / Pending / Approved / Rejected)\n2. Click a receipt row — **Review Modal** opens with receipt image on the left, form on the right\n3. Fill in transaction number (required), transaction date, and notes\n4. Add line items: click **\"Pick SKU\"** to open SKU picker, set quantity and price per line — `line_total` auto-computes\n5. Click **\"Preview Points\"** — calls `bff_approve_receipt_upload(action=''preview'')`, shows estimated points and duplicate warning if transaction number already exists\n6. Click **\"Approve\"** — calls `bff_approve_receipt_upload(action=''approve'')`, creates a purchase record in `purchase_ledger` + `purchase_items_ledger`, triggers the currency/tier/mission cascade\n7. Click **\"Reject\"** — opens rejection reason modal, marks receipt as rejected\n\n### 4b. View Customer Purchase History\n\n1. From **Customer 360**, search for a member by name/phone/email\n2. Navigate to the customer''s purchase history tab\n3. View transaction list with amounts, dates, status, and currency awarded\n\n### 4c. Common Admin Mistakes\n\n- Approving a receipt without line items — currency calculation may use `final_amount` only, missing product-specific multipliers\n- Duplicate transaction number — preview step warns, but approve step blocks with error\n- Wrong transaction date — affects tier evaluation window calculations", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/purchase-transactions.md#L66 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "12a1d7816e172950acbc180f8ebe2112f9ba986c77ecdd7884930cdcb875d452", "truncated": false}, "is_active": true}, {"id": "3fdc1b15-d707-58d8-9fda-035cd8151bcb", "feature_slug": "purchase-transactions", "title": "Data Integrity and Business Rules", "content": "### Core Principles\n\n1. **Immutability**: Completed transactions never modified, only reversed via debit records\n2. **Atomicity**: Transaction header and items created in single database transaction\n3. **Dual Perspective**: Same transaction can be buyer''s purchase and seller''s sale\n4. **Status-Driven Logic**: Business rules trigger on status transitions, not arbitrary events\n5. **Complete Audit**: All amounts preserved, reversal records linked to originals\n\n### Validation Rules\n\n**Transaction Level**:\n- `final_amount` must be positive for credit records\n- `transaction_number` unique within merchant\n- `user_id` must exist in user_accounts\n- `merchant_id` must match user''s merchant\n- Status transitions follow defined state machine\n\n**Line Item Level**:\n- `sku_id` must exist in product_sku_master\n- `quantity` must be positive\n- `line_total` should equal calculated amount\n- All line items must share transaction''s merchant_id\n\n**Refund Constraints**:\n- Debit records must reference original transaction\n- Refund amount cannot exceed original final_amount\n- Record_type must be ''debit''\n- Triggers currency reversal automatically\n\n### Edge Cases and Handling\n\n**Zero-Amount Transactions**:\n- Allowed for free samples, promotional giveaways\n- `final_amount = 0` earns 0 currency\n- Still creates transaction record for tracking\n- Can still trigger missions if conditions match\n\n**Negative Amounts**:\n- Not allowed in final_amount for credit records\n- Refunds use positive amounts with record_type = ''debit''\n- Calculation logic handles negation\n\n**Mixed Credit/Debit Queries**:\n- Sales metrics use CASE statement to negate debit records\n- Orders metrics exclude debit records entirely\n- Ensures accurate tier evaluation\n\n**Concurrent User Transactions**:\n- Multiple purchases can process simultaneously\n- Queue deduplication prevents evaluation spam\n- Each transaction independent until completion\n\n**Missing Line Items**:\n- Transaction can exist without items (valid for services)\n- Currency calculation uses transaction final_amount\n- Product-specific earn factors cannot apply\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Purchase_Transaction.md#L1153 Data Integrity and Business Rules", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ebae399638038777290050927df888de9f0196b9082ed76922f11456527e41ca", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
